settings.liquid:
{% comment %}
📱 Commandes SMS — Tableau (Shopify / Custom Liquid)
Collez ce bloc dans un "Liquid personnalisé" ou dans le contenu de page (mode HTML).
{% endcomment %}

<style>
  .sms-table-wrap{
    width:100%;
    margin: 18px 0;
  }
  .sms-table-title{
    font-size: 20px;
    margin: 0 0 10px 0;
  }
  .sms-table{
    width:100%;
    border-collapse: collapse;
    border: 1px solid rgba(0,0,0,.12);
    border-radius: 10px;
    overflow: hidden;
    background: #fff;
  }
  .sms-table th,
  .sms-table td{
    padding: 12px 14px;
    border-bottom: 1px solid rgba(0,0,0,.08);
    vertical-align: top;
    text-align: left;
    font-size: 14px;
    line-height: 1.4;
  }
  .sms-table th{
    background: rgba(0,0,0,.03);
    font-weight: 600;
  }
  .sms-table tr:last-child td{
    border-bottom: none;
  }
  .sms-code{
    display: inline-block;
    font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
    font-size: 13px;
    padding: 4px 8px;
    border-radius: 8px;
    background: rgba(0,0,0,.06);
    border: 1px solid rgba(0,0,0,.08);
    white-space: nowrap;
  }
  /* Responsive */
  @media (max-width: 768px){
    .sms-table th:nth-child(3),
    .sms-table td:nth-child(3){
      display:none; /* cache "Réponse de la centrale" sur mobile si tu veux alléger */
    }
  }
</style>

<div class="sms-table-wrap">
  <h3 class="sms-table-title">📱 Commandes SMS</h3>
  <p>Envoyez ces SMS au numéro de la carte SIM de votre centrale :</p>

  <table class="sms-table" role="table" aria-label="Commandes SMS centrale">
    <thead>
      <tr>
        <th>Action souhaitée</th>
        <th>SMS à envoyer</th>
        <th>Réponse de la centrale</th>
      </tr>
    </thead>
    <tbody>
      <tr>
        <td>Armer (mode absence)</td>
        <td><span class="sms-code">Away arm</span></td>
        <td><span class="sms-code">System armed!</span></td>
      </tr>
      <tr>
        <td>Mode maison (présence)</td>
        <td><span class="sms-code">Stay arm</span></td>
        <td><span class="sms-code">System armed!</span></td>
      </tr>
      <tr>
        <td>Désarmer</td>
        <td><span class="sms-code">Disarm</span></td>
        <td><span class="sms-code">System disarmed!</span></td>
      </tr>
    </tbody>
  </table>
</div>
